window.PP_BANKS=window.PP_BANKS||{};window.PP_BANKS["econ-150-ch17"]={"schema":"precise-practice/1","bank_id":"econ-150-ch17","book":"econ-150","chapter":17,"title":"Market Failures I: The Tragedy of the Commons","storage_version":1,"status":"draft","blueprint":"docs/blueprints/econ-150-ch17-commons.md","settings":{"goals":{"1":10,"2":10,"3":10}},"concepts":[{"id":"c1","number":1,"name":"The Commons Trap","activities":[{"id":"c1-textbook","type":"choice","tier":1,"title":"Textbook checks","targets":["17.1a"],"status":"draft","items":[{"id":"E17-C1-TB01","prompt":"A city draws groundwater from a basin shared by many towns, and each gallon pumped leaves fewer gallons for others. What kind of good is it, and which failure follows?","options":["A public good; the problem is underproduction.","A common resource; the problem is overuse.","A private good; the problem is monopoly pricing.","A club good; the problem is congestion only after admission."],"answer":1,"why":"The groundwater basin is difficult to exclude users from and rival in use: each gallon pumped leaves fewer gallons for others. That combination creates a common-resource overuse problem.","_v":"05b027c8de"},{"id":"E17-C1-TB02","prompt":"Which statement correctly distinguishes a common resource from a public good?","options":["A common resource is rival and hard to exclude; a public good is non-rival and hard to exclude.","A common resource is non-rival and easy to exclude; a public good is rival and easy to exclude.","Both are non-rival and hard to exclude, so both mainly suffer from underproduction.","Both are rival and hard to exclude, so both mainly suffer from depletion."],"answer":0,"why":"Both goods are difficult to exclude users from, but only a common resource is rival. Rivalry produces depletion and overuse; non-rivalry produces the public-good free-rider problem.","_v":"5fbc9a854a"}]},{"id":"c1-quick","type":"quick","tier":1,"title":"Quick classify","targets":["17.1a"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Private incentive","Collective outcome"],"round_size":10,"items":[{"id":"E17-C1-QK01","prompt":"A commuter takes one more trip on a toll-free road because the trip is valuable to that commuter.","answer":0,"why":"The commuter receives the immediate private benefit while road wear and delay are shared.","_v":"1e4d538523"},{"id":"E17-C1-QK02","prompt":"A driver avoids the road because every user is charged for the congestion they create.","answer":1,"why":"Charging for congestion makes the shared cost part of the user's decision.","_v":"356a2efeb7"},{"id":"E17-C1-QK03","prompt":"A public trail is open to all, and every extra visitor increases wear on the same path.","answer":0,"why":"Each visitor gets a private benefit while trail wear is shared.","_v":"0947003270"},{"id":"E17-C1-QK04","prompt":"A company owns a parking garage and controls entry.","answer":1,"why":"Clear ownership makes exclusion possible.","_v":"9cf66d7229"},{"id":"E17-C1-QK05","prompt":"A hiker keeps using a fragile trail because the damage from one more visit may be caused by someone else.","answer":0,"why":"Restraint is privately costly when other users remain free to visit.","_v":"aba465b621"},{"id":"E17-C1-QK06","prompt":"A city monitors permits and limits total daily access to a crowded park.","answer":1,"why":"Monitoring can make a shared-access rule credible.","_v":"c5e91e4730"},{"id":"E17-C1-QK07","prompt":"A rancher receives the extra value from adding one animal to a shared pasture.","answer":0,"why":"The rancher's private gain is concentrated while the grazing cost is shared.","_v":"dd5f0b4194"},{"id":"E17-C1-QK08","prompt":"A community limits groundwater withdrawals so the shared aquifer can recover.","answer":1,"why":"The limit changes the shared condition of the aquifer.","_v":"a7865a0885"},{"id":"E17-C1-QK09","prompt":"A household uses another unit of electricity because the immediate benefit is private.","answer":0,"why":"The immediate benefit is received by the individual household.","_v":"3382509bc5"},{"id":"E17-C1-QK10","prompt":"A neighborhood reports that a shared forest is recovering after a harvest rule.","answer":1,"why":"A recovering forest is a collective outcome.","_v":"33c4a02ab1"}]},{"id":"c1-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["17.1a"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Private incentive","Collective outcome"],"round_size":10,"cards":[{"id":"E17-C1-S01","text":"A commuter takes one more trip because the trip is valuable to that commuter.","bin":0,"why":"The commuter receives a private benefit from the extra trip.","_v":"57539e91ce"},{"id":"E17-C1-S02","text":"A driver avoids a road because every user is charged for congestion.","bin":1,"why":"The charge makes the shared congestion cost part of the decision.","_v":"c9f6c929a1"},{"id":"E17-C1-S03","text":"A public trail is open to all, and every visitor wears down the same path.","bin":0,"why":"Each visitor gets a private benefit while trail wear is shared.","_v":"e678a7e95e"},{"id":"E17-C1-S04","text":"A company owns a parking garage and controls entry.","bin":1,"why":"Clear ownership makes exclusion possible.","_v":"561cc52bda"},{"id":"E17-C1-S05","text":"A hiker keeps using a fragile trail because restraint would not stop others from visiting.","bin":0,"why":"Restraint is privately costly when others remain free to visit.","_v":"748d7383f8"},{"id":"E17-C1-S06","text":"A city monitors permits and limits total daily access to a crowded park.","bin":1,"why":"Monitoring can make a shared-access rule credible.","_v":"684221aea2"},{"id":"E17-C1-S07","text":"A rancher gains the full value of one more animal on a shared pasture.","bin":0,"why":"The rancher's private gain is concentrated while the grazing cost is shared.","_v":"5ae50efb49"},{"id":"E17-C1-S08","text":"A harvest rule lowers total tree cutting so a shared forest can recover.","bin":1,"why":"The rule protects the shared forest and its future users.","_v":"ee2eca795c"},{"id":"E17-C1-S09","text":"A household uses extra electricity because the next unit is useful to that household.","bin":0,"why":"The immediate benefit is received by the individual household.","_v":"9034adb638"},{"id":"E17-C1-S10","text":"A neighborhood agrees to leave part of a shared aquifer underground.","bin":1,"why":"The agreement protects the shared stock and its future users.","_v":"2447375f32"}]},{"id":"c1-match","type":"match","tier":1,"title":"Memory Match","targets":["17.1a"],"status":"draft","board_size":4,"pairs":[{"id":"E17-C1-M01","left":"Private benefit","right":"The gain received by the person making the choice","why":"A private benefit is the gain captured by the person who makes the choice.","_v":"e9f4a26da0"},{"id":"E17-C1-M02","left":"External cost","right":"A cost imposed on people outside the decision","why":"An external cost falls on people who were not part of the decision.","_v":"1eb7a7cc17"},{"id":"E17-C1-M03","left":"Commons","right":"A resource rival in use but difficult to exclude users from","why":"A commons is rival because one person's use leaves less for others, and difficult to exclude because access is open or costly to control.","_v":"3f376812f7"},{"id":"E17-C1-M04","left":"Collective action","right":"Coordinating behavior so a shared resource can be sustained","why":"Collective action means coordinating individual behavior so the shared resource is not overused.","_v":"0456990aae"}]},{"id":"c1-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["17.1a"],"status":"draft","rounds":[{"id":"c1-detective-r1","term":"The Commons Trap: Shared Public Spaces","answers":[{"text":"Each visitor receives a private benefit, but wear on the shared space is spread across users. The private benefit is larger than the cost felt by one visitor, so the common space can be depleted.","grade":"A","why":"This identifies both the individual incentive and the shared-resource consequence."},{"text":"Each visitor receives a private benefit, but wear on the shared space is spread across users.","grade":"A-","why":"This points toward the concept but leaves out the broader mechanism or consequence."},{"text":"The resource is safe because every user has an incentive to conserve it.","grade":"F","why":"The central problem is that private incentives can encourage use while the shared resource is depleted."}],"_v":"f8c2e9d3c9"}]},{"id":"c1-compare","type":"compare","tier":1,"title":"Compare the situations","targets":["17.1a"],"status":"draft","instructions":"Choose the situation with the stronger version of the concept.","labels":["A","B"],"round_size":10,"items":[{"id":"E17-C1-C01","prompt":"Which case creates the stronger commons problem?","left":"A private garden whose owner can exclude others","right":"A public trail where every visitor can use the same fragile path","answer":1,"why":"The open trail is difficult to exclude users from, and each visitor adds wear that others cannot avoid.","_v":"1835cdedfb"},{"id":"E17-C1-C02","prompt":"Which choice best reveals the private-versus-social gap?","left":"A commuter takes one more trip because the full trip benefit is private","right":"A commuter stops because the full congestion cost is personally charged","answer":0,"why":"The first case shows a private benefit while the shared congestion cost is not fully paid by the commuter.","_v":"35358e6f83"},{"id":"E17-C1-C03","prompt":"Which setting is easier to govern through ordinary private ownership?","left":"A fenced community garden with a clearly identified manager","right":"A public park open to every visitor without a daily limit","answer":0,"why":"A clear manager can bear the cost of overuse and control access.","_v":"7452b75d4e"},{"id":"E17-C1-C04","prompt":"Which situation is more likely to require a shared rule?","left":"One household deciding how much water to use from its own tank","right":"Many households drawing from a shared groundwater basin","answer":1,"why":"Many users can impose costs on one another when the groundwater basin is shared.","_v":"c72d9b92b5"}]},{"id":"c1-apply","type":"choice","tier":2,"title":"Applied cases","targets":["17.1a"],"status":"draft","items":[{"id":"E17-C1-AP01","prompt":"A city has no enforceable limit on cars entering a downtown zone. Each driver gets the trip's value, while congestion is spread across all drivers.","options":["Private incentives and social costs point in the same direction.","Each driver has reason to make more trips than the downtown zone can handle.","The road is non-rival because everyone can drive on it.","The problem disappears as long as drivers understand congestion."],"answer":1,"why":"Each driver receives the private benefit but bears only part of the congestion cost, creating an incentive to overuse the road.","_v":"641a30e15e"},{"id":"E17-C1-AP02","prompt":"A town gives one cooperative a monitored right to manage a public trail and exclude vehicles from fragile sections.","options":["The trail becomes non-rival for every visitor.","The cooperative can link access and monitoring to conservation.","The private benefit from visiting the trail disappears completely.","No rule is needed because ownership solves every problem."],"answer":1,"why":"Managed access can reduce the commons problem, but outcomes still depend on rules and enforcement.","_v":"2f5aa05cb5"},{"id":"E17-C1-AP03","prompt":"A student says, 'Traffic congestion happens because drivers are irrational.' Which response is strongest?","options":["The problem can result from rational choices under open access.","The student is right because rational people ignore incentives.","Traffic is a public good, so road use cannot be rival.","The problem is only a shortage caused by a temporary price."],"answer":0,"why":"The structure can make overuse individually sensible even when the collective result is harmful.","_v":"78f191f42d"},{"id":"E17-C1-AP04","prompt":"Which fact is most important for diagnosing a shared-road problem?","options":["Whether the resource is rival and hard to exclude users from","Whether every user has identical preferences","Whether the resource has a high market price","Whether the government owns the resource"],"answer":0,"why":"Rivalry and difficult exclusion are the defining conditions.","_v":"b4de99f333"},{"id":"E17-C1-AP05","prompt":"A rule limits the number of vehicles but is never monitored. What is the best prediction?","options":["The rule may have little effect if violations carry no expected consequence from enforcement.","The rule guarantees conservation because written rules usually work without monitoring.","The resource becomes non-rival because the rule limits who can use it.","Private benefits disappear because the rule removes every user's incentive."],"answer":0,"why":"A rule without credible monitoring or enforcement may not change behavior.","_v":"982604f300"}]},{"id":"c1-tiles","type":"tiles","tier":2,"title":"Economics ↔ English","targets":["17.1a"],"status":"draft","instructions":"Build the complete economic explanation from the tiles.","items":[{"id":"E17-C1-T01","title":"Why the trap persists","prompt":"Complete the explanation.","correct":["Each user receives the private benefit","but bears only part of the shared depletion cost"],"wrong":["so no user has any reason to conserve","because the shared space is non-rival"],"why":"The private benefit is concentrated while the depletion cost is spread across users.","hint":"Ask who receives the immediate benefit and who bears the shared loss.","_v":"a7cc11c9e5"},{"id":"E17-C1-T02","title":"Define the commons","prompt":"Complete the definition.","correct":["A commons is rival in use","and difficult to exclude users from"],"wrong":["A commons is non-rival","and automatically protected by ownership"],"why":"Both rivalry and difficult exclusion are needed for the commons problem.","hint":"Two properties matter: rivalry and exclusion.","_v":"ced8ab9f73"},{"id":"E17-C1-T03","title":"Why knowledge is not enough","prompt":"Complete the reasoning.","correct":["Even a well-informed user may keep taking","if leaving the resource means someone else takes it"],"wrong":["Information always solves the problem","because every user can wait forever"],"why":"The structure can make restraint privately costly when other users remain free to take.","hint":"Consider what happens when one visitor leaves a fragile trail for the next visitor.","_v":"50158b75c7"}]},{"id":"c1-calc","type":"calc","tier":2,"title":"Calculate the social cost","targets":["17.1a"],"status":"draft","generated_by":"draft-authoring","deck":{"formula":"Social cost = private cost + external cost","hint":"Add the cost paid by the decision-maker to the cost imposed on others.","worked_example":{"prompt":"A delivery trip costs the driver $4 and imposes $3 of congestion damage on other drivers.","steps":["Private cost = $4.","External cost = $3.","Social cost = $4 + $3 = $7."],"answer":"$7"},"rounding_rule":"Enter the numerical social cost.","progression":[1,3,5],"skill":"Compute a simple private-versus-social comparison.","problems":[{"id":"E17-C1-CL01","prompt":"A delivery trip costs the driver $4 and imposes $3 of congestion damage on other drivers. What is the social cost?","givens":{"private_cost":4,"external_cost":3},"answer":{"value":7,"tolerance":0.01,"decimals":2,"unit":"$"},"solution":["Private cost = $4.","External cost = $3.","Social cost = $4 + $3 = $7."],"common_errors":[],"status":"draft","_v":"8774ef7283"},{"id":"E17-C1-CL02","prompt":"A second car provides a private benefit of $9 but imposes $5 of congestion damage on other drivers. What is the combined private benefit minus external cost?","givens":{"private_benefit":9,"external_cost":5},"answer":{"value":4,"tolerance":0.01,"decimals":2,"unit":""},"solution":["Private benefit = $9.","External cost = $5.","Net social gain = $9 − $5 = $4."],"common_errors":[],"status":"draft","_v":"554b8add9b"},{"id":"E17-C1-CL03","prompt":"A parking rule reduces a driver's private convenience benefit from $10 to $8 but reduces shared congestion damage from $9 to $3. By how much does the net social result improve?","givens":{"before":1,"after":5},"answer":{"value":4,"tolerance":0.01,"decimals":2,"unit":""},"solution":["Before: $10 − $9 = $1.","After: $8 − $3 = $5.","Improvement = $5 − $1 = $4."],"common_errors":[],"status":"draft","_v":"90baf35051"}]}},{"id":"c1-ap","type":"choice","tier":3,"title":"AP-style review","targets":["17.1a"],"status":"draft","items":[{"id":"E17-C1-EX01","prompt":"A common resource is rival and non-excludable. Which policy argument follows most directly?","options":["Users may impose costs on one another, so limits may improve the shared outcome.","The resource is automatically a public good with no risk of overuse.","No policy can ever improve the result when access is difficult to control.","Every user must be forced to consume the same amount regardless of need."],"answer":0,"why":"Rivalry creates the possibility of depletion, while non-excludability makes access control difficult.","_v":"910b47be5d"},{"id":"E17-C1-EX02","prompt":"A community gives gardeners defined plots, monitors the shared garden, and applies graduated penalties. Which explanation best fits?","options":["The arrangement changes incentives and information without requiring one outside owner.","The arrangement makes harvesting non-rival by giving users defined rights.","Penalties matter only if every user receives the same punishment for a first violation.","Monitoring is irrelevant once rights are defined because users self-enforce."],"answer":0,"why":"Rights, monitoring, and graduated sanctions can make collective governance credible.","_v":"0ba140f909"},{"id":"E17-C1-EX03","prompt":"Which claim is most defensible about the tragedy of the commons?","options":["It is a predictable incentive problem, not simply proof that users are selfish.","It proves every shared resource must be privatized to avoid overuse.","It occurs only when the resource has no monetary price or formal rules.","It disappears whenever users know the resource is scarce and care about it."],"answer":0,"why":"The tragedy follows from the structure of incentives and access.","_v":"49a4124fdd"},{"id":"E17-C1-EX04","prompt":"Why might local rules outperform a one-size-fits-all rule in some commons?","options":["Local users may know the resource and monitor behavior at lower cost.","Local users never have conflicting interests or disagreements about rules.","Local rules cannot create exclusion or change anyone's access.","One-size-fits-all rules always ignore scarcity and local conditions."],"answer":0,"why":"Local knowledge and repeated interaction can support monitoring and adaptation.","_v":"c586c86e84"}]}]},{"id":"c2","number":2,"name":"The Commons, Part II","activities":[{"id":"c2-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["17.1b"],"status":"draft","items":[{"id":"E17-C2-TB01","prompt":"Why does a commuter keep driving even while watching congestion grow?","options":["The commuter gets the trip's value but bears only part of the delay cost; another driver can take the road space left unused.","The commuter thinks traffic will move faster when more cars enter the road.","The commuter personally bears the entire social cost of congestion.","The commuter is irrational because private benefits never matter on a shared road."],"answer":0,"why":"Private benefit is concentrated while the cost is shared. In open access, restraint is also privately costly because another user may take the road space.","_v":"bf448d7daa"},{"id":"E17-C2-TB02","prompt":"What best explains why the tragedy of the commons does not require greedy or short-sighted people?","options":["The incentives can make one more unit sensible even for a decent, far-sighted user.","Only greedy users can benefit from a common resource, while decent users cannot.","Far-sighted users solve the problem automatically by choosing restraint every time.","The tragedy occurs only when users misunderstand scarcity or lack information."],"answer":0,"why":"The problem is structural: each user receives the private gain while sharing the depletion cost, so individual restraint does not protect the resource.","_v":"071e9309c6"}]},{"id":"c2-quick","type":"quick","tier":1,"title":"Quick classify","targets":["17.2a"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Private incentive","Collective outcome"],"round_size":10,"items":[{"id":"E17-C2-QK01","prompt":"A commuter considers only the value of today's trip on a congested road.","answer":0,"why":"The future stock loss is spread across the whole group.","_v":"8fc840ec95"},{"id":"E17-C2-QK02","prompt":"A driver refuses one more trip because the full congestion cost is personally paid.","answer":1,"why":"The private and social incentives are aligned.","_v":"3da325f720"},{"id":"E17-C2-QK03","prompt":"A crowded park becomes less enjoyable as each visitor adds to the wear.","answer":0,"why":"The resource is rival, so one user's harvest leaves less for others.","_v":"bad1d3b3f3"},{"id":"E17-C2-QK04","prompt":"A private garage charges and controls access to its spaces.","answer":1,"why":"Exclusion makes the resource easier to manage.","_v":"9ad2b1ca4e"},{"id":"E17-C2-QK05","prompt":"A commuter says, 'My one trip cannot matter.'","answer":0,"why":"Many individually small choices can add up to a large collective effect.","_v":"0e79ed4f9e"},{"id":"E17-C2-QK06","prompt":"Visitors stop using a trail after erosion makes it unsafe.","answer":1,"why":"The collective outcome can feed back into everyone's future choices.","_v":"d25eae1fd8"},{"id":"E17-C2-QK07","prompt":"A software user keeps the private convenience from one more shared-server request.","answer":0,"why":"The revenue is a private incentive.","_v":"50a3d37176"},{"id":"E17-C2-QK08","prompt":"A seasonal closure lets a public forest regenerate.","answer":1,"why":"The closure protects the shared resource outcome.","_v":"f118c22a4f"},{"id":"E17-C2-QK09","prompt":"A user ignores a shared bandwidth cost because it falls on many others.","answer":0,"why":"The choice reflects a private incentive that omits a shared cost.","_v":"c234f7d63f"},{"id":"E17-C2-QK10","prompt":"A cooperative adjusts a park-entry limit after measuring crowding.","answer":1,"why":"The adjustment is a collective response to the resource condition.","_v":"bafcbaab56"}]},{"id":"c2-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["17.2a"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Private incentive","Collective outcome"],"round_size":10,"cards":[{"id":"E17-C2-S01","text":"A commuter considers only the value of today's trip on a congested road.","bin":0,"why":"The future stock loss is spread across the whole group.","_v":"768d5d55f6"},{"id":"E17-C2-S02","text":"A driver refuses one more trip because the full congestion cost is personally paid.","bin":1,"why":"The private and social incentives are aligned.","_v":"cd05e1e6ba"},{"id":"E17-C2-S03","text":"A crowded park becomes less enjoyable as each visitor adds to the wear.","bin":0,"why":"The resource is rival, so one user's harvest leaves less for others.","_v":"e91bee91cb"},{"id":"E17-C2-S04","text":"A private garage charges and controls access to its spaces.","bin":1,"why":"Exclusion makes the resource easier to manage.","_v":"6c481e448e"},{"id":"E17-C2-S05","text":"A commuter says, 'My one trip cannot matter.'","bin":0,"why":"Many individually small choices can add up to a large collective effect.","_v":"43ce556896"},{"id":"E17-C2-S06","text":"Visitors stop using a trail after erosion makes it unsafe.","bin":1,"why":"The collective outcome can feed back into everyone's future choices.","_v":"7dbf8e7b6a"},{"id":"E17-C2-S07","text":"A software user keeps the private convenience from one more shared-server request.","bin":0,"why":"The extra revenue is a private incentive for the captain.","_v":"90338503ec"},{"id":"E17-C2-S08","text":"A seasonal closure lets a public forest regenerate.","bin":1,"why":"A closure changes the shared resource's future condition.","_v":"80e85d368f"},{"id":"E17-C2-S09","text":"A user ignores a shared bandwidth cost because it falls on many others.","bin":0,"why":"The choice reflects a private incentive that omits a shared cost.","_v":"5363d0c46b"},{"id":"E17-C2-S10","text":"A cooperative adjusts a park-entry limit after measuring crowding.","bin":1,"why":"Shared monitoring and adjustment affect the collective outcome.","_v":"aaf2ec6baf"}]},{"id":"c2-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["17.2a"],"status":"draft","rounds":[{"id":"c2-detective-r1","term":"The Commons, Part II: Shared Roads","answers":[{"text":"The delay from one more car is spread across the whole group. The private and social incentives are misaligned. The road is rival in use, so one driver's trip leaves less capacity for others.","grade":"A","why":"This identifies both the individual incentive and the shared-resource consequence."},{"text":"The delay from one more car is spread across the whole group.","grade":"A-","why":"This points toward the concept but leaves out the broader mechanism or consequence."},{"text":"The resource is safe because every user has an incentive to conserve it.","grade":"F","why":"The central problem is that private incentives can encourage use while the shared resource is depleted."}],"_v":"ad9a20ae1b"}]}]},{"id":"c3","number":3,"name":"Two Solutions: Fences and Rules","activities":[{"id":"c3-textbook","type":"choice","tier":2,"title":"Textbook checks","targets":["17.1c"],"status":"draft","items":[{"id":"E17-C3-TB01","prompt":"Why is privatization a poor fix for carbon emissions into the atmosphere?","options":["The atmosphere has no practical boundary that one owner can draw, defend, and enforce.","Private ownership always makes pollution free by removing every external cost.","Carbon emissions are non-rival, so no policy is needed to address them.","Privatization works only when users have perfect information about emissions."],"answer":0,"why":"The global atmosphere cannot be enclosed and assigned to one owner in a workable way. Carbon is therefore usually addressed through rules, prices, or coordinated institutions.","_v":"8db6274821"},{"id":"E17-C3-TB02","prompt":"Which claim about privatization and government regulation is most accurate?","options":["Neither is universal: privatization needs boundaries; regulation needs enforcement and local knowledge.","Privatization always solves commons problems, so regulation is unnecessary in every setting and resource.","Government regulation always solves commons problems without enforcement, local information, or trade-offs.","Both fixes fail because common resources cannot be governed by any institution or local agreement."],"answer":0,"why":"The diagnosis of open-access overuse is general, but the appropriate remedy depends on whether boundaries, enforcement, and information are feasible.","_v":"e48e15ab0f"}]},{"id":"c3-quick","type":"quick","tier":1,"title":"Quick classify","targets":["17.3a"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Private incentive","Collective outcome"],"round_size":10,"items":[{"id":"E17-C3-QK01","prompt":"A neighborhood gives one manager a right to exclude outside users from a community garden.","answer":0,"why":"A fence attacks the exclusion problem directly.","_v":"6b84e60a74"},{"id":"E17-C3-QK02","prompt":"A town posts a traffic limit but never checks vehicles.","answer":1,"why":"A rule without monitoring may not change behavior.","_v":"9aa641244c"},{"id":"E17-C3-QK03","prompt":"A permit system limits who may enter a public forest.","answer":0,"why":"Permits can make access excludable while the shared resource remains rival.","_v":"34b0db0df3"},{"id":"E17-C3-QK04","prompt":"An owner bears the full cost of a depleted private pasture.","answer":1,"why":"The owner has a stronger reason to conserve.","_v":"97b225f43f"},{"id":"E17-C3-QK05","prompt":"A park rule changes when trail wear falls below a safe threshold.","answer":0,"why":"Adaptive rules can respond to changing conditions.","_v":"a4f8c764d3"},{"id":"E17-C3-QK06","prompt":"A written congestion rule has no penalty and violations are common.","answer":1,"why":"Credible enforcement is part of the solution.","_v":"190af22589"},{"id":"E17-C3-QK07","prompt":"A permit holder values the right to use one more unit of a shared resource.","answer":0,"why":"The value of the permit creates an individual incentive.","_v":"8adc1d011c"},{"id":"E17-C3-QK08","prompt":"A limit keeps daily visitors below the trail's replacement capacity.","answer":1,"why":"The limit protects the resource-wide outcome.","_v":"a97597a11f"},{"id":"E17-C3-QK09","prompt":"A user takes the last available parking space before another person can take it.","answer":0,"why":"The immediate private payoff drives the choice.","_v":"7aa17cb7df"},{"id":"E17-C3-QK10","prompt":"A community rule reduces congestion for all users.","answer":1,"why":"Reduced congestion is a collective consequence.","_v":"6ac0ef6439"}]},{"id":"c3-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["17.3a"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Private incentive","Collective outcome"],"round_size":10,"cards":[{"id":"E17-C3-S01","text":"A community gives one manager a right to exclude outside users from a garden.","bin":0,"why":"A fence attacks the exclusion problem directly.","_v":"92c696359a"},{"id":"E17-C3-S02","text":"A town posts a traffic limit but never checks vehicles.","bin":1,"why":"A rule without monitoring may not change behavior.","_v":"24231162f0"},{"id":"E17-C3-S03","text":"A permit system limits who may enter a public forest.","bin":0,"why":"Permits can make access excludable while the shared resource remains rival.","_v":"77a38f95b5"},{"id":"E17-C3-S04","text":"An owner bears the full cost of a depleted private pasture.","bin":1,"why":"The owner has a stronger reason to conserve.","_v":"bf6ee2f20a"},{"id":"E17-C3-S05","text":"A park rule changes when trail wear falls below a safe threshold.","bin":0,"why":"Adaptive rules can respond to changing conditions.","_v":"963bc03bbd"},{"id":"E17-C3-S06","text":"A written congestion rule has no penalty and violations are common.","bin":1,"why":"Credible enforcement is part of the solution.","_v":"b8ff732204"},{"id":"E17-C3-S07","text":"A permit holder values the right to use one more unit of a shared resource.","bin":0,"why":"The value of the permit creates an individual incentive.","_v":"19f4e04e26"},{"id":"E17-C3-S08","text":"A limit keeps daily visitors below the trail's replacement capacity.","bin":1,"why":"The limit protects the resource-wide outcome.","_v":"a14457a033"},{"id":"E17-C3-S09","text":"A user takes the last available parking space before another person can take it.","bin":0,"why":"The choice is driven by the harvester's immediate private payoff.","_v":"0be6ffd110"},{"id":"E17-C3-S10","text":"A community rule reduces congestion for all users.","bin":1,"why":"Reduced congestion is a collective consequence of the rule.","_v":"aa7e05e2c3"}]},{"id":"c3-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["17.3a"],"status":"draft","rounds":[{"id":"c3-detective-r1","term":"Two Solutions: Boundaries and Rules","answers":[{"text":"A gate attacks the access problem directly. A rule without monitoring may not change behavior. Permits can make access excludable while the shared resource remains rival.","grade":"A","why":"This identifies both the individual incentive and the shared-resource consequence."},{"text":"A gate attacks the access problem directly.","grade":"A-","why":"This points toward the concept but leaves out the broader mechanism or consequence."},{"text":"The resource is safe because every user has an incentive to conserve it.","grade":"F","why":"The central problem is that private incentives can encourage use while the shared resource is depleted."}],"_v":"e5fcdfeb57"}]}]},{"id":"c4","number":4,"name":"Ostrom's Third Way","activities":[{"id":"c4-textbook","type":"choice","tier":2,"title":"Textbook check","targets":["17.1d"],"status":"draft","items":[{"id":"E17-C4-TB01","prompt":"What did Elinor Ostrom's findings show about communities managing commons?","options":["Successful communities use local rules, monitoring, and sanctions; self-governance still requires institutions.","Communities solve commons problems by refusing to create rules or monitor behavior in any way.","Only privatization can prevent overuse when a resource is difficult to govern locally.","Local users cannot monitor a shared resource effectively without a distant authority or formal agency."],"answer":0,"why":"Ostrom showed that users can govern commons through locally designed institutions. Those institutions still require clear rules, monitoring, dispute resolution, and graduated sanctions.","_v":"a582d04b6a"}]},{"id":"c4-quick","type":"quick","tier":1,"title":"Quick classify","targets":["17.4a"],"status":"draft","instructions":"Choose the label that best describes the situation.","labels":["Private incentive","Collective outcome"],"round_size":10,"items":[{"id":"E17-C4-QK01","prompt":"Residents create a local rule after observing crowding in a public park.","answer":0,"why":"Local knowledge can help match rules to conditions.","_v":"3066ca9e87"},{"id":"E17-C4-QK02","prompt":"A distant authority imposes the same parking quota without learning local conditions.","answer":1,"why":"A one-size-fits-all rule may miss local information.","_v":"4577a4c5e4"},{"id":"E17-C4-QK03","prompt":"Residents monitor one another and apply graduated sanctions for trail damage.","answer":0,"why":"Monitoring and proportional sanctions can support cooperation.","_v":"d5ed0dae9e"},{"id":"E17-C4-QK04","prompt":"Every visitor is banned permanently after one small mistake.","answer":1,"why":"Graduated sanctions can preserve cooperation while responding to violations.","_v":"c68b259bf2"},{"id":"E17-C4-QK05","prompt":"Users participate in changing the rules for a shared community garden.","answer":0,"why":"Rule-making participation can increase legitimacy and information.","_v":"9af049dda1"},{"id":"E17-C4-QK06","prompt":"No one checks the resource or communicates with other users.","answer":1,"why":"Collective governance needs information, monitoring, and credible responses.","_v":"26dd6df21c"},{"id":"E17-C4-QK07","prompt":"A user follows a local rule because cooperation protects future access to the park.","answer":0,"why":"The expected private benefit supports compliance.","_v":"1f9a2b9208"},{"id":"E17-C4-QK08","prompt":"A monitoring group reports that the shared forest is recovering.","answer":1,"why":"The observation describes a shared resource outcome.","_v":"d1fa1deb1d"},{"id":"E17-C4-QK09","prompt":"A member saves effort today because a local sanction makes cheating costly.","answer":0,"why":"The sanction changes the member's private incentive.","_v":"7443a06b45"},{"id":"E17-C4-QK10","prompt":"Users revise the rule after public-trail use becomes scarce.","answer":1,"why":"Rule revision responds to a collective condition.","_v":"f627062b44"}]},{"id":"c4-sort","type":"sort","tier":1,"title":"Sort the cases","targets":["17.4a"],"status":"draft","instructions":"Sort each case into the category that best explains it.","bins":["Private incentive","Collective outcome"],"round_size":6,"cards":[{"id":"E17-C4-S01","text":"Residents create a local rule after observing crowding in a public park.","bin":0,"why":"Local knowledge can help match rules to conditions.","_v":"402966073e"},{"id":"E17-C4-S02","text":"A distant authority imposes the same parking quota without learning local conditions.","bin":1,"why":"A one-size-fits-all rule may miss local information.","_v":"35f36674c4"},{"id":"E17-C4-S03","text":"Residents monitor one another and apply graduated sanctions for trail damage.","bin":0,"why":"Monitoring and proportional sanctions can support cooperation.","_v":"bd8e763c26"},{"id":"E17-C4-S04","text":"Every visitor is banned permanently after one small mistake.","bin":1,"why":"Graduated sanctions can preserve cooperation while responding to violations.","_v":"283ff6d76c"},{"id":"E17-C4-S05","text":"Users participate in changing the rules for a shared community garden.","bin":0,"why":"Rule-making participation can increase legitimacy and information.","_v":"0dcfc6d4c2"},{"id":"E17-C4-S06","text":"No one checks the resource or communicates with other users.","bin":1,"why":"Collective governance needs information, monitoring, and credible responses.","_v":"11b5985ae6"},{"id":"E17-C4-S07","text":"A user follows a local rule because cooperation protects future access to the park.","bin":0,"why":"The user's expected private benefit supports compliance.","_v":"a0e5587a91"},{"id":"E17-C4-S08","text":"A monitoring group reports that the shared forest is recovering.","bin":1,"why":"The observation describes a shared resource outcome.","_v":"87e696f96e"},{"id":"E17-C4-S09","text":"A member saves effort today because a local sanction makes cheating costly.","bin":0,"why":"The sanction changes the member's private incentive.","_v":"133f7f413a"},{"id":"E17-C4-S10","text":"Users revise the rule after public-trail use becomes scarce.","bin":1,"why":"Rule revision responds to a collective condition of the resource.","_v":"6204913bb9"}]},{"id":"c4-detective","type":"detective","tier":1,"title":"Definition Detective","targets":["17.4a"],"status":"draft","rounds":[{"id":"c4-detective-r1","term":"Ostrom's Third Way","answers":[{"text":"Local knowledge can help match rules to conditions. A one-size-fits-all rule may miss local information. Monitoring and proportional sanctions can support cooperation.","grade":"A","why":"This identifies both the individual incentive and the shared-resource consequence."},{"text":"Local knowledge can help match rules to conditions.","grade":"A-","why":"This points toward the concept but leaves out the broader mechanism or consequence."},{"text":"The resource is safe because every user has an incentive to conserve it.","grade":"F","why":"The central problem is that private incentives can encourage use while the shared resource is depleted."}],"_v":"32300b301b"}]}]}],"readiness":{"streak":5,"items":[{"id":"E17-R01","prompt":"Why is an open-access public trail vulnerable to overuse?","options":["Each user gets the full visit benefit but shares the trail damage.","Each user pays the full trail damage but shares the visit benefit.","Trail use becomes non-rival when many visitors share the same path.","The trail closes because every visitor is irrational."],"answer":0,"why":"The private benefit is concentrated while the wear and damage are shared.","_v":"4b96816271"},{"id":"E17-R02","prompt":"What two properties define a common resource?","options":["Rivalry and difficult exclusion","Non-rivalry and easy exclusion","A high price and government ownership","Scarcity and equal incomes"],"answer":0,"why":"Common resources are rival in use and difficult to exclude users from.","_v":"4e9e8e35c0"},{"id":"E17-R03","prompt":"Why might a gate or fence help manage a crowded public trail?","options":["It can limit access and give a manager reason to protect the resource.","It makes the resource non-rival for every user and removes depletion.","It eliminates external costs without monitoring or additional rules.","It makes scarcity disappear by assigning ownership to a manager."],"answer":0,"why":"A gate attacks the access problem, though management still matters.","_v":"fb84248f9b"},{"id":"E17-R04","prompt":"Why can local governance work for a shared community garden?","options":["Local knowledge, monitoring, and sanctions can support cooperation.","Local users always agree about every rule and never disagree.","Local rules cannot be enforced by the users themselves at all.","Rules work only when imposed by a distant authority."],"answer":0,"why":"Those institutional features can support collective governance.","_v":"609d8738ec"},{"id":"E17-R05","prompt":"Is overuse of a shared public trail mainly a moral failure?","options":["It is a structural incentive problem, even when users understand it.","Yes; knowing the consequences makes the incentive problem disappear.","No; rational choices cannot occur in a commons under any conditions.","It occurs only when users are personally selfish rather than rational."],"answer":0,"why":"The structure can make overuse individually sensible even when it harms the group.","_v":"61f334fdaa"}],"spiral":[]},"version":"d538723ac2"};
